// Format the LLM response — handles both success and error from HTTP Request
const input = $input.item.json;
const prevData = $('Build Prompt').item.json;

let response = '';
let model = 'llama-70b';
let tokensUsed = 0;
let status = 'SUCCESS';

// Check if the HTTP Request node failed (continueOnFail)
const hasError = input.error || input.code === 'ERR_GOT_REQUEST_ERROR' || input.statusCode >= 400;

try {
  if (hasError) {
    status = 'LLM_ERROR';
    const errMsg = input.error?.message || input.message || input.statusMessage || 'LLM service unavailable';
    response = prevData.lang === 'fr'
      ? `Desole, le service LLM est temporairement indisponible (${errMsg}). Veuillez reessayer dans quelques instants.`
      : `Sorry, the LLM service is temporarily unavailable (${errMsg}). Please try again shortly.`;
  } else if (input.choices && input.choices.length > 0) {
    response = input.choices[0].message?.content || '';
    model = input.model || model;
    if (input.usage) {
      tokensUsed = input.usage.total_tokens || 0;
    }
  } else if (input.error) {
    // OpenRouter error response (e.g., rate limit)
    status = 'LLM_ERROR';
    const errMsg = input.error.message || JSON.stringify(input.error);
    response = prevData.lang === 'fr'
      ? `Erreur du service LLM : ${errMsg}`
      : `LLM service error: ${errMsg}`;
  }
} catch (e) {
  status = 'PARSE_ERROR';
  response = prevData.lang === 'fr'
    ? 'Erreur lors du traitement de la reponse LLM. Veuillez reessayer.'
    : 'Error processing LLM response. Please try again.';
}

if (!response || response.trim().length === 0) {
  status = 'EMPTY_RESPONSE';
  response = prevData.lang === 'fr'
    ? 'Le modele n\'a pas genere de reponse. Veuillez reformuler votre question.'
    : 'The model did not generate a response. Please rephrase your question.';
}

return {
  json: {
    status,
    response: response.trim(),
    query: prevData.query,
    lang: prevData.lang,
    model,
    tokens_used: tokensUsed,
    engine: 'PROJECT_CHATBOT_LLM',
    version: '2.0',
    timestamp: new Date().toISOString()
  }
};
